const records = new Map();
let processorCalls = 0;

function charge(reference, amountKobo) {
  const saved = records.get(reference);
  if (saved) return { ...saved, replayed: true };
  processorCalls += 1;
  const result = { chargeId: `ch_${processorCalls}`, amountKobo };
  records.set(reference, result);
  return { ...result, replayed: false };
}

