function checkServiceToken(header, expected) {
  const wanted = "Bearer " + expected;
  const given = header ?? "";
  let difference = given.length ^ wanted.length;
  for (let i = 0; i < wanted.length; i++) {
    difference |= (given.charCodeAt(i) || 0) ^ wanted.charCodeAt(i);
  }
  return difference === 0;
}

const token = "s3cr3t-internal-token";
console.log(checkServiceToken("Bearer s3cr3t-internal-token", token));
console.log(checkServiceToken("Bearer guessed-token", token));
console.log(checkServiceToken(undefined, token));
console.log(checkServiceToken("Bearer s3cr3t", token));

