const codes = ["RPC_UNAUTHENTICATED", "RPC_NOT_FOUND", "RPC_VALIDATION_ERROR", "RPC_TIMEOUT", "RPC_INTERNAL_ERROR", "RPC_TRANSPORT_ERROR"];

function httpStatusFor(rpcCode) {
  const map = { RPC_UNAUTHENTICATED: 401, RPC_NOT_FOUND: 404, RPC_VALIDATION_ERROR: 400 };
  if (["RPC_UNAVAILABLE", "RPC_TIMEOUT", "RPC_TRANSPORT_ERROR"].includes(rpcCode)) return 503;
  return map[rpcCode] ?? 500;
}

console.log(codes.map(httpStatusFor).join(" "));

function createLoyalty() {
  const handled = new Set();
  const balances = new Map();
  return {
    onOrderPaid(event) {
      if (handled.has(event.orderId)) return;
      handled.add(event.orderId);
      balances.set(event.email, (balances.get(event.email) ?? 0) + Math.floor(event.totalKobo / 100_000));
    },
    points: (email) => balances.get(email) ?? 0,
  };
}

const loyalty = createLoyalty();
const paid = { orderId: 7, email: "ada@example.ng", totalKobo: 2_850_000 };
loyalty.onOrderPaid(paid);
loyalty.onOrderPaid(paid);
loyalty.onOrderPaid({ orderId: 8, email: "ada@example.ng", totalKobo: 350_000 });
console.log(loyalty.points("ada@example.ng"));

