const outbox = [
  { id: 2, topic: "order.paid", orderId: 8, publishedAt: null },
  { id: 1, topic: "order.paid", orderId: 7, publishedAt: null },
  { id: 3, topic: "order.paid", orderId: 6, publishedAt: "2026-10-05T09:00:00Z" },
];
const published = [];

function relay(outbox, publish) {
  const due = outbox.filter((row) => row.publishedAt === null).sort((a, b) => a.id - b.id);
  for (const row of due) {
    publish(row);
    row.publishedAt = "now";
  }
  return due.length;
}

const publish = (row) => published.push(`${row.topic}#${row.orderId}`);
console.log(relay(outbox, publish), relay(outbox, publish));
console.log(published);

