async function placeOrder(order, chargeFn, retryQueue) {
  try {
    const result = await chargeFn(order);
    order.status = result === "succeeded" ? "paid" : "declined";
  } catch (error) {
    if (error.code !== "RPC_UNAVAILABLE") throw error;
    order.status = "pending_payment";
    retryQueue.push(order.id);
  }
  return order;
}

const retryQueue = [];
const down = async () => { throw Object.assign(new Error("payments.charge did not answer."), { code: "RPC_UNAVAILABLE" }); };
console.log(await placeOrder({ id: 1 }, async () => "succeeded", retryQueue));
console.log(await placeOrder({ id: 2 }, async () => "declined", retryQueue));
console.log(await placeOrder({ id: 3 }, down, retryQueue), retryQueue);

