const events = [
  { userId: "u-ada", email: "ada@example.ng", version: 1 },
  { userId: "u-ada", email: "ada.obi@example.ng", version: 3 },
  { userId: "u-ada", email: "ada@work.ng", version: 2 },
  { userId: "u-ada", email: "ada.obi@example.ng", version: 3 },
];

function apply(copy, event) {
  const current = copy.get(event.userId);
  if (current && current.version >= event.version) return;
  copy.set(event.userId, { email: event.email, version: event.version });
}

const copy = new Map();
for (const event of events) apply(copy, event);
console.log(copy);
